"""Render `docs/reference/backend/openapi.json` as the Markdown page `rest-api.md` beside it."""

import json
from pathlib import Path

from openapidocs.mk.v3 import OpenAPIV3DocumentationHandler

FOLDER = Path(__file__).parents[2] / "docs" / "reference" / "backend"

HEADER = """<!--
SPDX-FileCopyrightText: Manta contributors
SPDX-License-Identifier: CC-BY-4.0
-->
<!-- Generated by tools/docs/gen_rest_api.py from openapi.json. Do not edit: run `pixi run docs-rest-api`. -->

# REST API

This page lists every endpoint of Manta's REST API and the schemas they accept and return.
It is generated from the API's OpenAPI schema, `docs/reference/backend/openapi.json`.

"""


def render(spec: dict) -> str:
    body = OpenAPIV3DocumentationHandler(spec, style="MKDOCS").write()
    return HEADER + body[body.index("\n## ") + 1 :]


def main() -> None:
    spec = json.loads((FOLDER / "openapi.json").read_text())
    (FOLDER / "rest-api.md").write_text(render(spec))


if __name__ == "__main__":
    main()
